CREATE TABLE "pos_attendance_challenges" ("id" uuid PRIMARY KEY NOT NULL,"salon" text NOT NULL,"employee_id" text NOT NULL,"purpose" text NOT NULL,"action" text,"challenge" text NOT NULL,"origin" text NOT NULL,"rp_id" text NOT NULL,"expires_at" timestamp with time zone NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_attendance_records" ("id" uuid PRIMARY KEY NOT NULL,"salon" text NOT NULL,"employee_id" text NOT NULL,"employee_name" text NOT NULL,"work_date" text NOT NULL,"check_in_at" timestamp with time zone NOT NULL,"check_out_at" timestamp with time zone,"admin_verified_at" timestamp with time zone,"admin_verified_by" text,"check_in_admin_verified_at" timestamp with time zone,"check_in_admin_verified_by" text,"check_out_admin_verified_at" timestamp with time zone,"check_out_admin_verified_by" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_customers" ("phone" text PRIMARY KEY NOT NULL,"name" text NOT NULL,"points" integer DEFAULT 0 NOT NULL,"transaction_count" integer DEFAULT 0 NOT NULL,"total_spent" bigint DEFAULT 0 NOT NULL,"last_transaction_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_employee_attendance_auth" ("salon" text NOT NULL,"employee_id" text NOT NULL,"pin_salt" text NOT NULL,"pin_hash" text NOT NULL,"failed_attempts" integer DEFAULT 0 NOT NULL,"locked_until" timestamp with time zone,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,CONSTRAINT "pos_employee_attendance_auth_salon_employee_id_pk" PRIMARY KEY("salon","employee_id"));
CREATE TABLE "pos_employee_attendance_passkeys" ("id" text PRIMARY KEY NOT NULL,"salon" text NOT NULL,"employee_id" text NOT NULL,"public_key" text NOT NULL,"counter" bigint DEFAULT 0 NOT NULL,"transports" text[] DEFAULT '{}' NOT NULL,"device_type" text NOT NULL,"backed_up" boolean DEFAULT false NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_sales" ("id" uuid PRIMARY KEY NOT NULL,"salon" text DEFAULT 'beauty' NOT NULL,"invoice_number" text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"customer_name" text NOT NULL,"customer_phone" text,"cashier_name" text,"payment_method" text NOT NULL,"discount_mode" text DEFAULT 'nominal' NOT NULL,"discount_value" double precision DEFAULT 0 NOT NULL,"subtotal" integer NOT NULL,"discount" integer DEFAULT 0 NOT NULL,"total" integer NOT NULL,"amount_received" integer NOT NULL,"change_amount" integer DEFAULT 0 NOT NULL,"points_earned" integer DEFAULT 0 NOT NULL,"points_balance" integer DEFAULT 0 NOT NULL);
CREATE TABLE "pos_sale_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"sale_id" uuid NOT NULL REFERENCES "public"."pos_sales"("id") ON DELETE cascade,"line_index" integer NOT NULL,"service_id" text NOT NULL,"name" text NOT NULL,"unit_price" integer NOT NULL,"quantity" integer NOT NULL,"employee_id" text,"employee_name" text,"commission_percent" double precision DEFAULT 0 NOT NULL,"commission_base" integer DEFAULT 0 NOT NULL,"commission_amount" integer DEFAULT 0 NOT NULL);
CREATE TABLE "pos_salon_customers" ("salon" text NOT NULL,"phone" text NOT NULL,"member_code" uuid DEFAULT gen_random_uuid() NOT NULL,"name" text NOT NULL,"points" integer DEFAULT 0 NOT NULL,"transaction_count" integer DEFAULT 0 NOT NULL,"total_spent" bigint DEFAULT 0 NOT NULL,"last_transaction_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,CONSTRAINT "pos_salon_customers_salon_phone_pk" PRIMARY KEY("salon","phone"));
CREATE TABLE "pos_salon_employees" ("salon" text NOT NULL,"id" text NOT NULL,"name" text NOT NULL,"commission_percent" double precision NOT NULL,"active" boolean DEFAULT true NOT NULL,"is_cashier" boolean DEFAULT false NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,CONSTRAINT "pos_salon_employees_salon_id_pk" PRIMARY KEY("salon","id"));
CREATE TABLE "pos_salon_point_redemptions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"salon" text NOT NULL,"customer_phone" text NOT NULL,"customer_name" text NOT NULL,"points_spent" integer NOT NULL,"reward_name" text NOT NULL,"redeemed_by" text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_services" ("salon" text NOT NULL,"id" text NOT NULL,"name" text NOT NULL,"category" text NOT NULL,"sort_order" integer DEFAULT 0 NOT NULL,"min_price" integer NOT NULL,"max_price" integer,"price_type" text NOT NULL,"commission_percent" double precision,CONSTRAINT "pos_services_salon_id_pk" PRIMARY KEY("salon","id"));
CREATE TABLE "pos_expenses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"salon" text NOT NULL,"category" text NOT NULL,"description" text NOT NULL,"amount" integer NOT NULL,"expense_date" date NOT NULL,"payment_method" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_cashier_access_pins" ("account_id" text PRIMARY KEY NOT NULL,"pin_salt" text NOT NULL,"pin_hash" text NOT NULL,"failed_attempts" integer DEFAULT 0 NOT NULL,"locked_until" timestamp with time zone,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_salon_receipt_settings" ("salon" text PRIMARY KEY NOT NULL,"thank_you_text" text NOT NULL,"tagline_text" text NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_salon_promo_settings" ("salon" text PRIMARY KEY NOT NULL,"title" text DEFAULT '' NOT NULL,"description" text DEFAULT '' NOT NULL,"start_date" date,"end_date" date,"is_active" boolean DEFAULT false NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_whatsapp_campaigns" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"salon" text NOT NULL,"title" text NOT NULL,"campaign_type" text DEFAULT 'campaign' NOT NULL,"message" text NOT NULL,"created_by" text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_whatsapp_campaign_recipients" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"campaign_id" uuid NOT NULL REFERENCES "public"."pos_whatsapp_campaigns"("id") ON DELETE cascade,"salon" text NOT NULL,"phone" text NOT NULL,"customer_name" text NOT NULL,"status" text DEFAULT 'pending' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"sent_at" timestamp with time zone,"sent_by" text);
CREATE TABLE "pos_queue_bookings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"salon" text NOT NULL,"customer_name" text NOT NULL,"customer_phone" text,"service_id" text NOT NULL,"service_name" text NOT NULL,"employee_id" text NOT NULL,"employee_name" text NOT NULL,"scheduled_date" date NOT NULL,"scheduled_time" text NOT NULL,"notes" text,"status" text DEFAULT 'waiting' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "pos_salon_point_rewards" ("salon" text NOT NULL,"points" integer NOT NULL,"reward" text NOT NULL,CONSTRAINT "pos_salon_point_rewards_salon_points_pk" PRIMARY KEY("salon","points"));
CREATE INDEX "pos_attendance_challenges_expiry_idx" ON "pos_attendance_challenges" ("expires_at");
CREATE INDEX "pos_attendance_challenges_employee_idx" ON "pos_attendance_challenges" ("salon","employee_id");
CREATE UNIQUE INDEX "pos_attendance_records_employee_date_uidx" ON "pos_attendance_records" ("salon","employee_id","work_date");
CREATE INDEX "pos_attendance_records_salon_date_idx" ON "pos_attendance_records" ("salon","work_date");
CREATE INDEX "pos_employee_attendance_auth_salon_employee_idx" ON "pos_employee_attendance_auth" ("salon","employee_id");
CREATE INDEX "pos_employee_attendance_passkeys_employee_idx" ON "pos_employee_attendance_passkeys" ("salon","employee_id");
CREATE INDEX "pos_sale_items_sale_id_idx" ON "pos_sale_items" ("sale_id");
CREATE INDEX "pos_sales_created_at_idx" ON "pos_sales" ("created_at");
CREATE INDEX "pos_sales_customer_phone_idx" ON "pos_sales" ("customer_phone");
CREATE INDEX "pos_salon_customers_salon_points_idx" ON "pos_salon_customers" ("salon","points");
CREATE UNIQUE INDEX "pos_salon_customers_member_code_idx" ON "pos_salon_customers" ("member_code");
CREATE INDEX "pos_salon_employees_salon_active_idx" ON "pos_salon_employees" ("salon","active");
CREATE INDEX "pos_salon_point_redemptions_customer_idx" ON "pos_salon_point_redemptions" ("salon","customer_phone","created_at");
CREATE INDEX "pos_salon_point_redemptions_created_at_idx" ON "pos_salon_point_redemptions" ("salon","created_at");
CREATE INDEX "pos_services_salon_category_idx" ON "pos_services" ("salon","category");
CREATE INDEX "pos_expenses_salon_date_idx" ON "pos_expenses" ("salon","expense_date");
CREATE UNIQUE INDEX "pos_whatsapp_campaign_recipients_campaign_phone_uidx" ON "pos_whatsapp_campaign_recipients" ("campaign_id","phone");
CREATE INDEX "pos_whatsapp_campaign_recipients_campaign_status_idx" ON "pos_whatsapp_campaign_recipients" ("campaign_id","status");
CREATE INDEX "pos_whatsapp_campaign_recipients_salon_phone_idx" ON "pos_whatsapp_campaign_recipients" ("salon","phone");
CREATE INDEX "pos_whatsapp_campaigns_salon_created_at_idx" ON "pos_whatsapp_campaigns" ("salon","created_at");
CREATE INDEX "pos_queue_bookings_salon_date_time_idx" ON "pos_queue_bookings" ("salon","scheduled_date","scheduled_time");
CREATE INDEX "pos_queue_bookings_salon_status_idx" ON "pos_queue_bookings" ("salon","status");
CREATE INDEX "pos_salon_point_rewards_salon_idx" ON "pos_salon_point_rewards" ("salon");
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['pos_attendance_challenges','pos_attendance_records','pos_customers','pos_employee_attendance_auth','pos_employee_attendance_passkeys','pos_sale_items','pos_sales','pos_salon_customers','pos_salon_employees','pos_salon_point_redemptions','pos_services','pos_expenses','pos_cashier_access_pins','pos_salon_receipt_settings','pos_salon_promo_settings','pos_whatsapp_campaign_recipients','pos_whatsapp_campaigns','pos_queue_bookings','pos_salon_point_rewards'] LOOP
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;